# ─────────────────────────────────────────────
# اللوجو المتحرك (نسخة زرقاء) + اسم RAMBO AI TV تحته
# قابل لإعادة الاستخدام في كل صفحة (الترحيبية + الترتيب الذكي + النقل)
# ─────────────────────────────────────────────
def render_rambo_logo(compact=False, show_tagline=True):
    size = 92 if compact else 280
    ring_size = 66 if compact else 200
    wrap = 140 if compact else 380
    title_size = 22 if compact else 56
    pad = "16px 20px 10px" if compact else "34px 20px 26px"
    back_font1 = 15 if compact else 40
    back_font2 = 10 if compact else 24
    flip_seconds = 4.5 if compact else 5.5

    particles_html = "" if compact else """
        <div class="particle p1">📡</div>
        <div class="particle p2">🎬</div>
        <div class="particle p3">✨</div>
        <div class="particle p4">🔁</div>
    """

    tagline_html = "" if not show_tagline else """
      <div class="rambo-sub">⚡ أول موقع مصري ذكي لترتيب ملف قنوات الرسيفرات الداخليه للشاشات بالذكاء الاصطناعي</div>
      <div class="rambo-slogan">مع رامبو خلصانة في ثانية الا ثانية ⚡</div>
    """

    logo_html = f"""
    <div style="width:100%; display:flex; justify-content:center; background:transparent;">
    <style>
    @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@700;900&family=Cairo:wght@700;900&display=swap');

    .rambo-hero {{
        position: relative;
        width: 100%;
        max-width: 820px;
        padding: {pad};
        text-align: center;
        font-family: 'Cairo', sans-serif;
        overflow: visible;
        direction: rtl;
    }}

    .logo-wrap {{
        position: relative;
        width: {wrap}px;
        height: {wrap}px;
        margin: 0 auto 14px;
        display: flex;
        align-items: center;
        justify-content: center;
    }}

    .ring {{
        position: absolute;
        top: 50%; left: 50%;
        width: {ring_size}px; height: {ring_size}px;
        border-radius: 50%;
        border: 2px solid #29b6ff;
        transform: translate(-50%, -50%) scale(0.5);
        opacity: 0;
        animation: ringPulse 3s ease-out infinite;
    }}
    .ring:nth-child(2) {{ animation-delay: 1s; border-color: #0066ff; }}
    .ring:nth-child(3) {{ animation-delay: 2s; }}

    @keyframes ringPulse {{
        0%   {{ transform: translate(-50%, -50%) scale(0.5); opacity: 0.9; }}
        70%  {{ opacity: 0.15; }}
        100% {{ transform: translate(-50%, -50%) scale(2.6); opacity: 0; }}
    }}

    /* ── العملة الدائرية اللي بتلف بين الصورة واللوجو النصي ── */
    .coin-outer {{
        position: relative;
        z-index: 2;
        width: {size}px; height: {size}px;
        perspective: 1000px;
    }}

    .coin {{
        position: relative;
        width: 100%; height: 100%;
        transform-style: preserve-3d;
        animation: coinFlip {flip_seconds}s cubic-bezier(.45,.05,.55,.95) infinite;
    }}

    .coin-face {{
        position: absolute;
        inset: 0;
        border-radius: 50%;
        overflow: hidden;
        backface-visibility: hidden;
        -webkit-backface-visibility: hidden;
        border: 3px solid #0099ff;
        box-shadow: 0 0 20px rgba(0,153,255,0.65), 0 0 45px rgba(41,182,255,0.35);
        animation: badgeGlow 2.4s ease-in-out infinite;
        display: flex;
        align-items: center;
        justify-content: center;
    }}

    .coin-face.coin-front {{
        background: #0a1420;
    }}

    .coin-face.coin-front img {{
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }}

    .coin-face.coin-front::after {{
        content: "";
        position: absolute;
        inset: 0;
        background: repeating-linear-gradient(
            to bottom,
            rgba(255,255,255,0.07) 0px,
            rgba(255,255,255,0.07) 1px,
            transparent 2px,
            transparent 4px
        );
        animation: scanMove 4.5s linear infinite;
        pointer-events: none;
        mix-blend-mode: overlay;
    }}

    .coin-face.coin-back {{
        transform: rotateY(180deg);
        background:
            repeating-conic-gradient(from 0deg, #16233a 0deg 90deg, #0c1626 90deg 180deg);
        flex-direction: column;
        font-family: 'Orbitron', 'Cairo', sans-serif;
        font-weight: 900;
        text-align: center;
        color: #eaf6ff;
        line-height: 1.15;
    }}

    .coin-back-line1 {{
        font-size: {back_font1}px;
        letter-spacing: 1px;
        text-shadow: 0 0 10px #0099ff, 0 0 20px rgba(41,182,255,0.65);
    }}

    .coin-back-line2 {{
        font-size: {back_font2}px;
        color: #66c9ff;
        margin-top: 4px;
        text-shadow: 0 0 8px rgba(0,153,255,0.6);
    }}

    @keyframes coinFlip {{
        0%   {{ transform: rotateY(0deg); }}
        45%  {{ transform: rotateY(0deg); }}
        55%  {{ transform: rotateY(180deg); }}
        95%  {{ transform: rotateY(180deg); }}
        100% {{ transform: rotateY(360deg); }}
    }}

    @keyframes scanMove {{
        0%   {{ transform: translateY(0); }}
        100% {{ transform: translateY(8px); }}
    }}

    @keyframes badgeGlow {{
        0%, 100% {{ box-shadow: 0 0 20px rgba(0,153,255,0.55), 0 0 40px rgba(41,182,255,0.30); }}
        50%      {{ box-shadow: 0 0 32px rgba(0,153,255,0.9), 0 0 60px rgba(41,182,255,0.55); }}
    }}

    .particle {{
        position: absolute;
        font-size: 18px;
        opacity: 0;
        animation: floatUp 5s ease-in infinite;
    }}
    .particle.p1 {{ left: 8%;  top: 70%; animation-delay: 0s; }}
    .particle.p2 {{ left: 82%; top: 68%; animation-delay: 1.4s; }}
    .particle.p3 {{ left: 20%; top: 10%; animation-delay: 2.6s; }}
    .particle.p4 {{ left: 74%; top: 8%;  animation-delay: 3.6s; }}

    @keyframes floatUp {{
        0%   {{ transform: translateY(0) scale(0.8); opacity: 0; }}
        15%  {{ opacity: 0.9; }}
        100% {{ transform: translateY(-70px) scale(1.1); opacity: 0; }}
    }}

    .rambo-title {{
        font-family: 'Orbitron', 'Cairo', sans-serif;
        font-weight: 900;
        font-size: {title_size}px;
        letter-spacing: 1px;
        color: #eaf6ff;
        margin: 6px 0 2px;
        animation: flicker 4.5s linear infinite;
        text-shadow: 0 0 10px #0099ff, 0 0 24px rgba(0,153,255,0.55), 0 0 40px rgba(41,182,255,0.35);
    }}

    @keyframes flicker {{
        0%, 92%, 100% {{ opacity: 1; }}
        93% {{ opacity: 0.55; }}
        94% {{ opacity: 1; }}
        95% {{ opacity: 0.7; }}
        96% {{ opacity: 1; }}
    }}

    .rambo-sub {{
        font-size: 17px;
        color: #8fd6ff;
        margin-top: 2px;
    }}

    .rambo-slogan {{
        font-family: 'Cairo', sans-serif;
        font-weight: 900;
        font-size: 24px;
        color: #66c9ff;
        margin: 6px 0 4px;
        text-shadow: 0 0 12px rgba(0,153,255,0.6);
        animation: sloganGlow 2.4s ease-in-out infinite;
    }}

    @keyframes sloganGlow {{
        0%, 100% {{ text-shadow: 0 0 8px rgba(0,153,255,0.45); }}
        50%      {{ text-shadow: 0 0 20px rgba(0,153,255,0.95), 0 0 30px rgba(41,182,255,0.4); }}
    }}
    </style>

    <div class="rambo-hero">
      <div class="logo-wrap">
        <div class="ring"></div>
        <div class="ring"></div>
        <div class="ring"></div>
        <div class="coin-outer">
          <div class="coin">
            <div class="coin-face coin-front">
              <img src="data:image/webp;base64,__LOGO_B64_PLACEHOLDER__" alt="Rambo AI TV" />
            </div>
            <div class="coin-face coin-back">
              <div class="coin-back-line1">RAMBO</div>
              <div class="coin-back-line2">AI TV</div>
            </div>
          </div>
        </div>
        {particles_html}
      </div>
      <div class="rambo-title">RAMBO AI TV</div>
      {tagline_html}
    </div>
    </div>
    """
    return logo_html.replace("__LOGO_B64_PLACEHOLDER__", _LOGO_B64)


# ─────────────────────────────────────────────
# ديمو متحرك بسيط (زي GIF) يوضح إزاي المستخدم يغيّر فئة القناة بالدراج والدروب
# ─────────────────────────────────────────────
def render_dragdrop_demo():
    return """
<h2 class="sr-only"></h2>
<div style="background:#160f22; border-radius:12px; padding:1.5rem;">
  <div style="color:#c9a3ff; font-size:14px; margin-bottom:1rem; text-align:right; direction:rtl;">اسحب الفئة لمكانها الجديد — الترقيم بيتحدّث تلقائي</div>
  <div id="pills" style="position:relative; width:100%; height:280px;"></div>
</div>
<script>
const cats = [
  ['ديني مسيحي',34],['كوميديا',6],['أفلام عربي',48],['أفلام أجنبي',24],
  ['مسلسلات ودراما',86],['أخبار',98],['قنوات رسمية ودولية',53],['أطفال',35],
  ['موسيقى وأغاني',14],['وثائقي وثقافي',15],['رياضة',98],['أسرة وطبخ',4],
  ['ديني إسلامي',79],['ألعاب',6],['راديو',254],['تجريبي وفحص',110],['منوعات عامة',299]
];
const originalOrder = cats.map((c,i) => i);
let order = originalOrder.slice();
const wrap = document.getElementById('pills');
const pillEls = {};
const TR = 'left .9s cubic-bezier(.4,0,.2,1), top .9s cubic-bezier(.4,0,.2,1)';

function makeHand(){
  const h = document.createElement('div');
  h.style.cssText = 'position:absolute; right:-18px; top:50%; transform:translateY(-50%) scale(0); width:30px; height:30px; opacity:0; transition:opacity .25s, transform .25s; pointer-events:none;';
  h.innerHTML = '<svg width="30" height="30" viewBox="0 0 30 30"><ellipse cx="8" cy="15" rx="4.5" ry="5.5" fill="#f0c9a0" stroke="#160f22" stroke-width="1.2"/><rect x="9" y="9" width="15" height="15" rx="6.5" fill="#f0c9a0" stroke="#160f22" stroke-width="1.2"/></svg>';
  return h;
}

cats.forEach((c, idx) => {
  const el = document.createElement('div');
  el.style.cssText = 'position:absolute; display:flex; align-items:center; gap:8px; background:#241a35; border:0.5px solid #3a2a52; border-radius:999px; padding:6px 10px 6px 6px; font-size:13px; color:#eee; white-space:nowrap; transition:'+TR+', transform .5s, border-color .3s; z-index:1;';
  el.innerHTML = '<span class="num" style="background:#d4537e;color:#4b1528;width:22px;height:22px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:500;">1</span><span>'+c[0]+' ('+c[1]+')</span>';
  el.appendChild(makeHand());
  wrap.appendChild(el);
  pillEls[idx] = el;
});

const ripple = document.createElement('div');
ripple.style.cssText = 'position:absolute; width:14px; height:14px; border-radius:50%; background:#d4537e; opacity:0; z-index:8; pointer-events:none;';
wrap.appendChild(ripple);

function layout(orderArr){
  const containerWidth = wrap.clientWidth;
  let x = containerWidth;
  let y = 0;
  const pos = {};
  orderArr.forEach((idx, i) => {
    const w = pillEls[idx].offsetWidth;
    if (x - w < 0){ x = containerWidth; y += 46; }
    x -= w;
    pos[idx] = { left: x, top: y, rank: i };
    x -= 10;
  });
  Object.keys(pos).forEach(idx => {
    pillEls[idx].style.left = pos[idx].left + 'px';
    pillEls[idx].style.top = pos[idx].top + 'px';
    pillEls[idx].querySelector('.num').textContent = pos[idx].rank + 1;
  });
  return pos;
}

function pulseAt(x, y){
  ripple.style.transition = 'none';
  ripple.style.left = (x - 7) + 'px';
  ripple.style.top = (y - 7) + 'px';
  ripple.style.opacity = '0.7';
  ripple.style.transform = 'scale(0.4)';
  requestAnimationFrame(() => {
    ripple.style.transition = 'transform .5s ease-out, opacity .5s ease-out';
    ripple.style.transform = 'scale(2.4)';
    ripple.style.opacity = '0';
  });
}

function wait(ms){ return new Promise(r => setTimeout(r, ms)); }

async function dragTo(dragIdx, newRank){
  const el = pillEls[dragIdx];
  const hand = el.querySelector('div');
  el.style.zIndex = '5';
  hand.style.opacity = '1';
  hand.style.transform = 'translateY(-50%) scale(1)';
  await wait(500);

  let pt = { x: el.offsetLeft + el.offsetWidth, y: el.offsetTop + el.offsetHeight / 2 };
  pulseAt(pt.x, pt.y);
  el.style.borderColor = '#d4537e';
  el.style.transform = 'scale(1.06)';
  await wait(350);

  order = order.filter(i => i !== dragIdx);
  order.splice(newRank, 0, dragIdx);
  layout(order);
  await wait(1000);

  pt = { x: el.offsetLeft + el.offsetWidth, y: el.offsetTop + el.offsetHeight / 2 };
  pulseAt(pt.x, pt.y);
  el.style.transform = 'scale(1)';
  el.style.borderColor = '#3a2a52';
  await wait(300);
  hand.style.opacity = '0';
  hand.style.transform = 'translateY(-50%) scale(0)';
  el.style.zIndex = '1';
}

async function loop(){
  layout(order);
  await wait(1000);
  while(true){
    await dragTo(5, 0);
    await wait(900);
    await dragTo(14, 1);
    await wait(2400);

    order = originalOrder.slice();
    layout(order);
    await wait(2200);
  }
}
loop();
</script>"""


# ─────────────────────────────────────────────
# ديمو متحرك بسيط (زي GIF) يوضح إزاي المستخدم يغيّر رقم ترتيب القناة يدويًا
# ─────────────────────────────────────────────
def render_reorder_demo():
    return """
<div class="rank-demo">
  <style>
    .rank-demo{ font-family:'Cairo', sans-serif; direction:rtl; color:#e8e6f5; max-width:520px; margin:0 auto; }
    .rank-steps{ display:flex; flex-wrap:wrap; gap:8px; justify-content:center; margin-bottom:18px; }
    .rank-step{ background:#170f2e; border:1px solid #3a2a5c; border-radius:20px; padding:8px 14px; font-size:13px; color:#9fb0c9; transition: all .25s ease; }
    .rank-step.active{ background:rgba(0,240,255,0.12); border-color:#00f0ff; color:#a6f3ff; box-shadow:0 0 10px rgba(0,240,255,.3); }
    .rank-list{ position:relative; height:176px; margin:0 6px; }
    .rank-row{ position:absolute; right:0; left:0; height:36px; display:flex; align-items:center; gap:10px;
      background:#170f2e; border:1px solid #3a2a5c; border-radius:8px; padding:0 12px;
      transition: top .6s cubic-bezier(.4,0,.2,1), border-color .3s ease; }
    .rank-row.highlight{ border-color:#ff007f; }
    .rank-num{ display:inline-flex; align-items:center; justify-content:center; min-width:26px; height:24px;
      background:#1f1440; border:1px solid #3a2a5c; border-radius:6px; font-size:13px; font-weight:700;
      color:#00f0ff; transition: border-color .3s ease, box-shadow .3s ease; }
    .rank-num.editing{ border-color:#ff007f; box-shadow:0 0 8px rgba(255,0,127,.5); color:#ff9ecb; }
    .rank-name{ font-size:13px; color:#e8e6f5; }
    .rank-cursor{ position:absolute; font-size:20px; top:-6px; right:-4px; opacity:0; transition: opacity .3s ease; filter:drop-shadow(0 2px 3px rgba(0,0,0,.6)); }
    .rank-cursor.show{ opacity:1; }
  </style>
  <div class="rank-steps">
    <span class="rank-step" id="rkS1">1️⃣ دوس على خانة الرقم</span>
    <span class="rank-step" id="rkS2">2️⃣ امسح الرقم واكتب رقم جديد</span>
    <span class="rank-step" id="rkS3">3️⃣ دوس Enter — القناة بتتحرك لمكانها فورًا ✔</span>
  </div>
  <div class="rank-list" id="rankList">
    <div class="rank-row" id="rowSky" style="top:0px;">
      <span class="rank-num" id="numSky">1</span><span class="rank-name">Sky News</span>
    </div>
    <div class="rank-row" id="rowDrama" style="top:44px;">
      <span class="rank-num" id="numDrama">2</span><span class="rank-name">MBC Drama</span>
    </div>
    <div class="rank-row" id="rowFox" style="top:88px; position:absolute;">
      <span class="rank-num" id="numFox">3</span><span class="rank-name">Fox Movies</span>
      <span class="rank-cursor" id="rkCursor">👆</span>
    </div>
    <div class="rank-row" id="rowNatgeo" style="top:132px;">
      <span class="rank-num" id="numNatgeo">4</span><span class="rank-name">Nat Geo</span>
    </div>
  </div>
</div>
<script>
(function(){
  var s1=document.getElementById('rkS1'), s2=document.getElementById('rkS2'), s3=document.getElementById('rkS3');
  var rowSky=document.getElementById('rowSky'), rowDrama=document.getElementById('rowDrama');
  var rowFox=document.getElementById('rowFox'), rowNatgeo=document.getElementById('rowNatgeo');
  var numSky=document.getElementById('numSky'), numDrama=document.getElementById('numDrama');
  var numFox=document.getElementById('numFox'), numNatgeo=document.getElementById('numNatgeo');
  var cursor=document.getElementById('rkCursor');

  function reset(){
    [s1,s2,s3].forEach(function(s){ s.classList.remove('active'); });
    rowSky.style.top='0px'; rowDrama.style.top='44px'; rowFox.style.top='88px'; rowNatgeo.style.top='132px';
    numSky.textContent='1'; numDrama.textContent='2'; numFox.textContent='3'; numNatgeo.textContent='4';
    numFox.classList.remove('editing');
    rowFox.classList.remove('highlight');
    cursor.classList.remove('show');
  }

  function run(){
    reset();
    setTimeout(function(){
      rowFox.classList.add('highlight');
      cursor.classList.add('show');
      s1.classList.add('active');
    }, 300);
    setTimeout(function(){
      s1.classList.remove('active'); s2.classList.add('active');
      numFox.classList.add('editing');
      numFox.textContent = '';
    }, 1400);
    setTimeout(function(){ numFox.textContent = '1'; }, 1900);
    setTimeout(function(){
      s2.classList.remove('active'); s3.classList.add('active');
      cursor.classList.remove('show');
      numFox.classList.remove('editing');
      rowFox.style.top = '0px';
      rowSky.style.top = '44px';
      rowDrama.style.top = '88px';
      numSky.textContent = '2';
      numDrama.textContent = '3';
    }, 2700);
    setTimeout(function(){ rowFox.classList.remove('highlight'); }, 3400);
    setTimeout(run, 5200);
  }
  run();
})();
</script>
"""



# ─────────────────────────────────────────────
# ستايل عام: هوية الموقع + إخفاء شريط Streamlit + فرض RTL في كل حتة
# ─────────────────────────────────────────────
st.markdown("""
<style>
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700;900&family=Cairo:wght@400;600;700;900&display=swap');

header[data-testid="stHeader"] { display: none !important; }
#MainMenu { display: none !important; }
div[data-testid="stToolbar"] { display: none !important; }
div[data-testid="stDecoration"] { display: none !important; }
div[data-testid="stStatusWidget"] { display: none !important; }
footer { display: none !important; }

/* إخفاء السايدبار بالكامل ولينك التنقل التلقائي بتاعه (مش مستخدمين سايدبار خالص) */
section[data-testid="stSidebar"] { display: none !important; }
div[data-testid="stSidebarNav"] { display: none !important; }
div[data-testid="collapsedControl"] { display: none !important; }

html, body,
[data-testid="stAppViewContainer"],
[data-testid="stAppViewBlockContainer"],
[data-testid="stMainBlockContainer"],
section.main,
.main,
.block-container,
[data-testid="block-container"],
div.stApp,
.stApp {
    background: radial-gradient(circle at 50% 50%, #110926 0%, #05020d 100%) !important;
    background-color: #05020d !important;
}

/* ── فرض اتجاه RTL على كل عناصر الصفحة، عشان ميحصلش تشتت بين
      العربي والإنجليزي (الترتيب البصري بيبقى صح تلقائي مع RTL) ── */
[data-testid="stAppViewContainer"],
[data-testid="stAppViewBlockContainer"],
.block-container {
    direction: rtl !important;
}

[data-testid="stAppViewContainer"] p,
[data-testid="stAppViewContainer"] li,
[data-testid="stAppViewContainer"] span,
[data-testid="stAppViewContainer"] label,
[data-testid="stAppViewContainer"] h1,
[data-testid="stAppViewContainer"] h2,
[data-testid="stAppViewContainer"] h3,
[data-testid="stAppViewContainer"] h4,
[data-testid="stAppViewContainer"] div[data-testid="stMarkdownContainer"] {
    direction: rtl !important;
    text-align: right !important;
}

/* أعمدة st.columns بتتقلب تلقائي عشان أول عنصر يفضل جهة اليمين */
div[data-testid="stHorizontalBlock"] {
    direction: rtl !important;
}
div[data-testid="stHorizontalBlock"] > div {
    direction: rtl !important;
}

.main {
    font-family: 'Cairo', sans-serif !important;
}

.block-container {
    padding-top: 0.5rem !important;
    max-width: 100% !important;
}

h2 {
    color: #00f0ff !important;
    text-shadow: 0 0 5px #00f0ff !important;
    font-family: 'Orbitron', 'Cairo' !important;
    font-weight: 700 !important;
    text-align: center !important;
}

h3, h4 {
    color: #00f0ff !important;
    font-family: 'Cairo' !important;
    font-weight: 700 !important;
}

p, label, .stMarkdown, .stBody {
    color: #e0e0e0 !important;
    font-size: 18px !important;
    line-height: 1.9 !important;
}

.center-text,
[data-testid="stAppViewContainer"] .center-text,
[data-testid="stAppViewContainer"] h3.center-text,
[data-testid="stAppViewContainer"] p.center-text {
    text-align: center !important;
}

hr { border-color: #00f0ff !important; opacity: 0.5 !important; }

/* أزرار عادية (زي "روح لصفحة كذا") */
div[data-testid="stButton"] > button {
    background: linear-gradient(135deg, #ff007f 0%, #aa0055 100%) !important;
    color: #ffffff !important;
    border: 2px solid #ff007f !important;
    border-radius: 14px !important;
    font-weight: bold !important;
    font-size: 17px !important;
    padding: 12px 20px !important;
    box-shadow: 0 0 15px rgba(255,0,127,0.4) !important;
    font-family: 'Cairo' !important;
    width: 100%;
}

/* ── شريط التبويب العلوي (مبني بـ st.radio عشان نقدر نتحكم فيه
      برمجيًا من أي زرار تاني، وشكله زي التابات بالظبط) ── */
div[data-testid="stRadio"] > div[role="radiogroup"] {
    display: flex;
    flex-direction: row-reverse;
    gap: 10px;
    justify-content: center;
    border-bottom: 2px solid rgba(0,240,255,0.25);
    padding-bottom: 14px;
    margin-bottom: 6px;
}
div[data-testid="stRadio"] label {
    background: rgba(255,255,255,0.04);
    border: 2px solid rgba(0,240,255,0.35);
    border-radius: 12px 12px 0 0;
    padding: 10px 20px !important;
    cursor: pointer;
    transition: all 0.2s ease;
}
div[data-testid="stRadio"] label:hover {
    border-color: #ff007f;
}
div[data-testid="stRadio"] label div[data-testid="stMarkdownContainer"] p {
    font-family: 'Cairo', sans-serif !important;
    font-weight: 800 !important;
    font-size: 17px !important;
    color: #9fe8ef !important;
    margin: 0 !important;
}
div[data-testid="stRadio"] label[data-checked="true"],
div[data-testid="stRadio"] label:has(input:checked) {
    background: rgba(255,0,127,0.14);
    border-color: #ff007f;
    box-shadow: 0 0 14px rgba(255,0,127,0.35);
}
div[data-testid="stRadio"] label:has(input:checked) div[data-testid="stMarkdownContainer"] p {
    color: #ff007f !important;
    text-shadow: 0 0 8px rgba(255,0,127,0.5);
}
/* اخفاء دوائر الراديو الافتراضية عشان يبقى شكله زي تابات مش راديو */
div[data-testid="stRadio"] label > div:first-child {
    display: none;
}
</style>
""", unsafe_allow_html=True)

# ─────────────────────────────────────────────
# شريط التابات الثلاثة (مبني بحيث أي زرار في الصفحة يقدر يودّي له مباشرة)
# ─────────────────────────────────────────────
HOME_LABEL = "🏠 الصفحة الترحيبية"
SMART_LABEL = "🗂️ الترتيب الذكي بالفئات"
TRANSFER_LABEL = "🔁 نقل الترتيب بين ملفين"

if "active_tab" not in st.session_state:
    st.session_state.active_tab = HOME_LABEL


def go_to(label):
    st.session_state.active_tab = label


st.radio(
    "التنقل بين الصفحات",
    [HOME_LABEL, SMART_LABEL, TRANSFER_LABEL],
    horizontal=True,
    key="active_tab",
    label_visibility="collapsed",
)

active = st.session_state.active_tab

# ترجيع الصفحة لأولها كل مرة نتنقل بين التابات (بمحاولات متكررة عشان نضمن
# إنها تنفّذ بعد ما Streamlit يخلص يرسم الصفحة الجديدة بالكامل)
components.html(
    f"""
    <script>
    function scrollAppToTop() {{
        try {{
            var doc = window.parent.document;
            var containers = [
                doc.querySelector('[data-testid="stAppViewContainer"]'),
                doc.querySelector('[data-testid="stMain"]'),
                doc.querySelector('section.main'),
                doc.documentElement,
                doc.body
            ];
            containers.forEach(function(el) {{
                if (el) {{ el.scrollTop = 0; }}
            }});
            window.parent.scrollTo(0, 0);
        }} catch (e) {{}}
    }}
    scrollAppToTop();
    [0, 50, 150, 300, 500, 800].forEach(function(t) {{
        setTimeout(scrollAppToTop, t);
    }});
    </script>
    <!-- {active} -->
    """,
    height=0,
)

# ===================== الصفحة الترحيبية =====================
if active == HOME_LABEL:
    components.html(render_rambo_logo(compact=False, show_tagline=True), height=610, scrolling=False)

    st.markdown("---")

    st.header("🌟 وظيفة كل صفحة في الموقع")

    col_smart, col_transfer = st.columns(2)

    with col_smart:
        st.markdown(
            "<h3 class='center-text'>🗂️ الترتيب الذكي بالفئات</h3>",
            unsafe_allow_html=True,
        )
        st.markdown(
            "<p class='center-text'>ارفع ملف قنواتك، والموقع بيحللها ويصنّفها تلقائيًا حسب المحتوى "
            "(ديني، رياضة، أفلام، مسلسلات، أطفال، أخبار...) وبيرتبها حسب الأولوية اللي تحددها انت. "
            "تقدر تعدّل أي تصنيف يدوي، وتشوف النتيجة أول بأول قبل ما تنزّل الملف الجاهز للتشغيل.</p>",
            unsafe_allow_html=True,
        )
        st.button(
            "🗂️ روح لصفحة الترتيب الذكي",
            key="btn_go_smart",
            on_click=go_to,
            args=(SMART_LABEL,),
            use_container_width=True,
        )

    with col_transfer:
        st.markdown(
            "<h3 class='center-text'>🔁 نقل الترتيب بين ملفين</h3>",
            unsafe_allow_html=True,
        )
        st.markdown(
            "<p class='center-text'>عندك ملف قنوات لقيته على النت وعجبك ترتيبه؟ ارفعه مع ملف قنوات شاشتك الحالي، "
            "والموقع هيدوّر على القنوات المشتركة بالاسم وينقل لك نفس الترتيب على ملفك فورًا — "
            "من غير ما يلمس الترددات أو أي بيانات تقنية تانية.</p>",
            unsafe_allow_html=True,
        )
        st.button(
            "🔁 روح لصفحة نقل الترتيب",
            key="btn_go_transfer",
            on_click=go_to,
            args=(TRANSFER_LABEL,),
            use_container_width=True,
        )

    st.markdown("---")

    st.header("🎓 إزاي تستخدم الأداة؟")

    st.markdown(
        "<h3 class='center-text'>🗂️ تغيير فئة أي قناة (دراج آند دروب)</h3>",
        unsafe_allow_html=True,
    )
    st.markdown(
        "<p class='center-text'>تقدر بكل بساطة تدوس على الفئه "
        "وتسحبها بالماوس لتحديد اولويه االفئات.</p>",
        unsafe_allow_html=True,
    )
    components.html(render_dragdrop_demo(), height=420, scrolling=False)

    st.markdown("---")

    st.markdown(
        "<h3 class='center-text'>🔢 تغيير ترتيب رقم القناة</h3>",
        unsafe_allow_html=True,
    )
    st.markdown(
        "<p class='center-text'>عاوز قناة معينة تبقى رقم تاني في الترتيب؟ دوس على خانة الرقم بتاعتها، "
        "امسح الرقم القديم واكتب الرقم الجديد، ودوس Enter — باقي القنوات هتترتب لوحدها تلقائيًا حواليها.</p>",
        unsafe_allow_html=True,
    )
    components.html(render_reorder_demo(), height=320, scrolling=False)

    st.markdown("---")
    st.markdown(
        "<p class='center-text' style='color:#00f0ff; font-size:15px;'>"
        "للعلم بيتم عمل تحديثات للموقع يوميًا لمواكبة التحديثات التكنولوجية الجديدة</p>",
        unsafe_allow_html=True,
    )
    st.markdown(
        "<p class='center-text' style='color:#9fb0c9; font-size:12px; letter-spacing:2px;'>"
        "DEVELOPED BY RAFIK NATHAN</p>",
        unsafe_allow_html=True,
    )


# ===================== الترتيب الذكي بالفئات =====================
elif active == SMART_LABEL:
    components.html(render_rambo_logo(compact=True, show_tagline=False), height=170, scrolling=False)
    components.html(get_tool_html(default_page="smart"), height=2200, scrolling=True)

# ===================== نقل الترتيب بين ملفين =====================
elif active == TRANSFER_LABEL:
    components.html(render_rambo_logo(compact=True, show_tagline=False), height=170, scrolling=False)
    components.html(get_tool_html(default_page="transfer"), height=2200, scrolling=True)
